<div class="filter-search"><label for="q" class="form-label">{{ $mine ?? false ? 'Search your courses' : 'Search students' }}</label><input id="q" name="q" value="{{ $filters['q'] ?? '' }}" class="form-control" maxlength="120" placeholder="{{ $mine ?? false ? 'Course title…' : 'Student name or email…' }}"></div>
<div><label for="status" class="form-label">Enrollment status</label><select id="status" name="status" class="form-select"><option value="active" @selected(($filters['status'] ?? 'active') === 'active')>Active</option><option value="withdrawn" @selected(($filters['status'] ?? '') === 'withdrawn')>Withdrawn</option><option value="all" @selected(($filters['status'] ?? '') === 'all')>All enrollments</option></select></div>
